-- MOCK ACADEMICO - 20/11/2026
-- REEMPLAZA el seed original: ejecutar UNA VEZ sobre el esquema de la app VACIO.
-- No ejecutar encima de los datos originales: conserva IDs y habria colisiones.
-- No borra tablas ni datos. Hacer rollback si el cliente SQL informa un error.
-- Solo INSERTs sobre las tablas/columnas observadas; el adjunto no incluia DDL.
-- Validado en SQLite con esquema inferido, no contra modelos/constraints de la app.
-- 40 alumnos (tipo 1) por cada una de las 8 carreras + administrador = 321 usuarios.
-- Conserva usuarios 1..19, mails, nombres de login y hashes originales.
-- Nuevos usuarios: estudiante<ID>@example.com / estudiante<ID>.
-- Su hash es el mismo de alumno@test.com; la clave en texto plano NO fue provista.
-- Perfiles demo: 2 (jperez): 18 aprobadas, 2 regulares, 3 cursando.
--                3 (diego): 19 aprobadas, 2 regulares, 3 cursando.
-- Mitad aproximada de las 37 materias no electivas (45 incluyendo 8 electivas).
-- 135 cursos = 3 comisiones por cada una de las 45 materias originales.
-- dias es bitmask: Lun=1, Mar=2, Mie=4, Jue=8, Vie=16; sin Sab/Dom.
-- duracion en minutos POR CLASE. No hay solapamientos en inscripciones actuales.
-- Estados, correlativas, inscripciones y actividades de cursada estan alineados.
-- Anuales y segundo cuatrimestre como cursadas actuales a noviembre de 2026.
-- Las 7 carreras restantes tienen planes ficticios identificados como de prueba.
-- No se inventaron sus catalogos de materias: no estaban incluidos en el adjunto.
-- Esos alumnos tienen perfiles, amistades y grupos, sin historial academico inventado.
-- Se conservan facultades y catalogo de Sistemas del original, sin verificacion oficial.
-- Materiales: se conservan rutas originales; los PDFs NO se incluyen en este archivo.
-- Calificaciones de materiales, likes y descargas son datos de simulacion independientes.
-- Las reseñas describen cursos pasados; inscripciones_cursos contiene solo cursadas actuales.
-- Los horarios son sinteticos, no una oferta academica oficial.
-- tipos_usuarios: 3 filas.
-- carreras: 8 filas.
-- planes_academicos: 9 filas.
-- usuarios: 321 filas.
-- materias: 45 filas.
-- correlativas_x_materia: 87 filas.
-- cursos: 135 filas.
-- perfiles: 321 filas.
-- estado_materia_alumno: 938 filas.
-- inscripciones_cursos: 158 filas.
-- amistades: 1005 filas.
-- grupos: 8 filas.
-- grupo_miembros: 96 filas.
-- grupo_mensajes: 32 filas.
-- materiales_estudio: 24 filas.
-- material_calificaciones: 96 filas.
-- foro_publicaciones: 120 filas.
-- foro_comentarios: 359 filas.
-- foro_reacciones: 441 filas.
-- actividad: 478 filas.
-- encuestas_catedra: 156 filas.


